{"op":"add","path":"/root","value":"main"}
{"op":"add","path":"/elements/main","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg"},"children":["header","picker-card","laptops-grid","specs-card","charts-grid","verdict-card"]}}
{"op":"add","path":"/elements/header","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"children":["title","intro"]}}
{"op":"add","path":"/elements/title","value":{"type":"Heading","props":{"text":"Compare Laptops: Aero 14 vs Forge 16 vs Nimbus 13","level":"h1"},"children":[]}}
