{"op":"add","path":"/elements/priority","value":{"type":"RadioGroup","props":{"options":["Portability & battery","Performance","Lowest price","Best display & balance"],"value":{"$bindState":"/priority"}},"children":[]}}
{"op":"add","path":"/elements/rec-nimbus","value":{"type":"Alert","props":{"title":"Recommended: Nimbus 13 — $999","description":"Lightest (1.0 kg), longest battery (22 h) and $300 less than the Aero 14. Watch out for the 256 GB SSD."},"visible":{"$or":[{"$state":"/priority","eq":"Portability & battery"},{"$state":"/priority","eq":"Lowest price"}]},"children":[]}}
{"op":"add","path":"/elements/rec-forge","value":{"type":"Alert","props":{"title":"Recommended: Forge 16 — $1,899","description":"16-core 55 W CPU, 32 GB upgradeable RAM, 1 TB SSD and every port you need. Expect 2.1 kg and audible fans."},"visible":{"$state":"/priority","eq":"Performance"},"children":[]}}
{"op":"add","path":"/elements/rec-aero","value":{"type":"Alert","props":{"title":"Recommended: Aero 14 — $1,299","description":"Highest rated (4.6★) with a gorgeous OLED, 18 h battery and just 1.2 kg. The best all-rounder."},"visible":{"$or":[{"$state":"/priority","eq":"Best display & balance"},{"$state":"/priority","not":true}]},"children":[]}}
{"op":"add","path":"/state/priority","value":"Best display & balance"}
