{"op":"add","path":"/elements/lap-cons","value":{"type":"List","props":{"items":{"$item":"cons"}},"children":[]}}
{"op":"add","path":"/elements/lap-best","value":{"type":"Text","props":{"text":{"$template":"Best for: ${bestFor}"},"variant":"small"},"children":[]}}
